mapper.select:
SELECT
    a.*,
    d.design_name
FROM
    flowable_apply a
LEFT JOIN
    flowable_process_design d ON d.design_code = a.design_code AND d.deleted = 0
WHERE
    a.deleted = 0
     AND a.apply_code = #{applyCode} 
     AND a.design_code = #{designCode} 
     AND a.business_type = #{businessType} 
     AND a.status = #{status} 
     AND a.start_user_id = #{startUserId} 
     AND a.tenant_code = #{tenantCode} 
ORDER BY
    a.id DESC
